function MONO_TRIPLES(n, c):
    bad <- empty list
    for x from 1 to n:
        for y from x to n:
            z <- x + y
            if z > n: break        # sums only grow
            if c[x] = c[y] = c[z]:
                append (x, y, z) to bad
    return bad
function IS_SCHUR_COLORING(n, c):
    return MONO_TRIPLES(n, c) is empty

