function FIND_COLORING(r, n):
    for tail in all (n-1)-tuples over {0,...,r-1}:
        assignment <- (0,) ++ tail        # color(1)=0 by symmetry
        c[k] := assignment[k-1]
        if IS_SCHUR_COLORING(n, c): return assignment
    return NONE
function SCHUR_NUMBER(r):
    best <- 0
    for n from 1 upward:
        if FIND_COLORING(r, n) != NONE: best <- n
        else: break                       # monotonicity
    return best

